"use client"

import {
  HoverCard as HoverCardRoot,
  HoverCardContent as HoverCardPopup,
  HoverCardTrigger as HoverCardTriggerPart,
} from "@ui-sdk/react/hover-card"
import type * as React from "react"

import { cn } from "cn"

function HoverCard({ ...props }: React.ComponentProps<typeof HoverCardRoot>) {
  return <HoverCardRoot {...props} />
}

function HoverCardTrigger({ ...props }: React.ComponentProps<typeof HoverCardTriggerPart>) {
  return <HoverCardTriggerPart {...props} />
}

function HoverCardContent({
  className,
  side = "bottom",
  sideOffset = 4,
  align = "center",
  alignOffset = 4,
  ...props
}: React.ComponentProps<typeof HoverCardPopup>) {
  return (
    <HoverCardPopup
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
      className={cn(
        "z-50 w-64 origin-(--transform-origin) rounded-lg bg-popover p-2.5 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden duration-100 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
        className
      )}
      {...props}
    />
  )
}

export { HoverCard, HoverCardTrigger, HoverCardContent }
